{
  "PROP-57888860-inv-028": {
    "property_id": "PROP-57888860-inv-028",
    "audit_result": {
      "property_id": "PROP-57888860-inv-028",
      "classification": "potential-vulnerability",
      "code_path": "beacon_node/beacon_chain/src/data_column_verification.rs::verify_data_column_sidecar::L532-561",
      "proof_trace": "Gossip validation checks index bounds (<NUMBER_OF_COLUMNS) but does not verify index matches positional column_index in iteration. An attacker can send sidecars with swapped indices (e.g., index=5 at position 0), passing validation but violating the invariant that downstream code assumes.",
      "attack_scenario": "Malicious peer sends DataColumnSidecar with index=N at array position M (N\u2260M). Gossip verification accepts it (bounds check passes). Downstream KZG operations using cell_ids.push(data_column.index) at line 396 of reconstruct_data_columns will use wrong column indices for cryptographic verification, potentially causing incorrect reconstruction or bypassing data availability guarantees.",
      "checklist_id": "PROP-57888860-inv-028"
    },
    "text": "Each DataColumnSidecar.index must equal its positional column_index in the iteration.",
    "assertion": "forall get_data_column_sidecars -> sidecars: sidecars[i].index == i for all i in range(NUMBER_OF_COLUMNS)",
    "covers": "SG-003",
    "severity": "MEDIUM",
    "type": "invariant"
  }
}

